describe("SL-004 reject empty and over-long titles", () => {
  let server: Running;

  before(async () => {
    server = await startServer();
  });
  after(async () => {
    await server?.stop();
  });

  async function assertRejected(response: Response, code: string): Promise<void> {
    assert.equal(response.status, 400);
    const body = (await response.json()) as { error: { code: string; message: string } };
    assert.equal(body.error.code, code);
    assert.equal(typeof body.error.message, "string");
  }

  for (const [name, title] of [
    ["empty", ""],
    ["whitespace-only", "   \t\n "],
    ["501 characters", "a".repeat(501)],
    ["501 characters after trimming", `  ${"a".repeat(501)}  `],
  ] as const) {
    it(`a ${name} title is rejected with 400 validation_failed and nothing is stored`, async () => {
      await assertRejected(await createTask(server, title), "validation_failed");
      assert.deepEqual(await listTasks(server), []);
    });
  }

  it("a missing or non-string title is rejected with 400 validation_failed", async () => {
    for (const body of [{}, { title: 42 }, { title: null }, null]) {
      const response = await fetch(`${server.baseUrl}/api/tasks`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(body),
      });
      await assertRejected(response, "validation_failed");
    }
  });

  it("a body that is not JSON is rejected with 400 invalid_json", async () => {
    const response = await fetch(`${server.baseUrl}/api/tasks`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: "{not json",
    });
    await assertRejected(response, "invalid_json");
  });

  it("a title of exactly 500 characters, or 1 character, is accepted", async () => {
    assert.equal((await createTask(server, "a".repeat(500))).status, 201);
    assert.equal((await createTask(server, "a")).status, 201);
    assert.equal((await createTask(server, `  ${"b".repeat(500)}  `)).status, 201);
  });
});
EOF
